package com.masaakis.kitchen.api;import com.masaakis.kitchen.application.KitchenService;import com.masaakis.security.StaffPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.net.URI;import java.util.*;
@RestController@RequestMapping("/api/admin/kitchen")public class KitchenController{private final KitchenService service;public KitchenController(KitchenService s){service=s;}@GetMapping KitchenService.KitchenOverview overview(@AuthenticationPrincipal StaffPrincipal p){return service.overview(p);}@PostMapping("/stations")ResponseEntity<Map<String,UUID>>create(@AuthenticationPrincipal StaffPrincipal p,@Valid@RequestBody StationRequest r){UUID id=service.createStation(p,r.name(),r.sortOrder(),r.categoryIds());return ResponseEntity.created(URI.create("/api/admin/kitchen/stations/"+id)).body(Map.of("id",id));}@GetMapping("/stations/{id}/queue")List<KitchenService.KitchenItem>queue(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id){return service.queue(p,id);}@PatchMapping("/items/{id}")ResponseEntity<Void>item(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id,@Valid@RequestBody ItemState r){service.itemState(p,id,r.state());return ResponseEntity.noContent().build();}public record StationRequest(@NotBlank@Size(max=120)String name,@Min(0)@Max(10000)int sortOrder,@NotEmpty List<UUID>categoryIds){}public record ItemState(@Pattern(regexp="PREPARING|DONE")String state){}}
